  function BottomNav(){const r=route();const active=r.startsWith('/explorer')?'explorer':r.startsWith('/commandes')?'orders':r.startsWith('/compte')?'account':'home';const items=[['home','/accueil','Accueil'],['explorer','/explorer','Explorer'],['receipt','/commandes','Commandes'],['user','/compte','Compte']];return items.map(([ico,path,label])=>`<a href="${path}" data-route="${path}" class="bottom-item ${active===({home:'home',explorer:'explorer',receipt:'orders',user:'account'})[ico]?'active':''}">${svg(ico)}<span>${label}</span>${ico==='receipt'&&store.orders.some(o=>!['delivered','cancelled','refunded'].includes(o.status))?'<i class="nav-dot"></i>':''}</a>`).join('');}
